For every integer $n\ge1$,
\begin{equation}
 a(n+1)=\prod_{k=1}^{n}
 \left(1-2\left(\floor{\frac{k^n}{n}}
                  -\floor{\frac{k^n-1}{n}}\right)\right)
 =(-1)^{n/\rad(n)}
 =\begin{cases}1,&4\mid n,\\-1,&4\nmid n.\end{cases}
\end{equation}
All division inside a floor is rational division; in particular the
subtraction by $1$ precedes the second division.

We have $I_0=1$, $I_1=1/2$, and, for $m\ge2$,
\begin{equation}
 I_m=\begin{cases}
 -1/(m^2-1),&m\ \text{even},\\
 1/(m+1),&m\equiv1\pmod4,\\
 -1/(m-1),&m\equiv3\pmod4.
 \end{cases}
\end{equation}
Consequently $a(0)=1$ and, for $m\ge1$, $a(m)=1$ exactly when
$m\equiv1\pmod4$, and $a(m)=-1$ otherwise. Also
\begin{equation}
 d(0)=1,\qquad
 d(m)=\begin{cases}
 m^2-1,&m\ge2\ \text{even},\\
 m+1,&m\equiv1\pmod4,\\
 m-1,&m\equiv3\pmod4.
 \end{cases}
\end{equation}
The odd branches include $m=1$ in the second case.

For positive integers $k,s$, the group $\Gk$ has an $s$-spanning pair
if and only if one of the following conditions holds:
\begin{align*}
&s\text{ is odd}, &&2k\le s^2-1;\\
&s\text{ is even}, &&2k\le s^2-s;\\
&s\equiv0\pmod4,\quad k\text{ is even},
&&s^2-s<2k\le s^2;\\
&s\equiv2\pmod4,\quad k\equiv2\pmod4,
&&s^2-s<2k\le s^2.
\end{align*}

For $n\geq1$, $v=\val(n)$, every integer $r\geq1$, and every function
$w$ on the positive integers with complex values,
\begin{equation}
 \sum_{d\mid n}m(d)^r w(d)=w(1)+2^r\sum_{j=1}^v w(2^j).
\end{equation}

For real $a\geq0$, set $F_a(n)=\sum_{j=0}^{\val(n)}2^{aj}$.
Then
\begin{align*}
 \sum_{n\geq1}F_a(n)x^n
 &=\sum_{j\geq0}\frac{2^{aj}x^{2^j}}{1-x^{2^j}}
 &&(|x|<1),\\
 \sum_{n\geq1}\frac{F_a(n)}{n^s}
 &=\frac{\zeta(s)}{1-2^{a-s}}
 &&(\Re s>\max\{1,a\}).
\end{align*}
The cases $a=1,2,3$ are A038712, A296306, A318935, respectively.
Also $F_0(n)=\val(n)+1$
and $\sum_{d\mid n}m(d)=2F_0(n)-1=H_{3589}(n)$.

The metric $d$ is of negative type, and all nonempty principal submatrices
of $Z$ are positive definite. The deletion procedure stops after two solves
with
\begin{equation}
 p=\frac1{61601}(15961,22820,0,0,22820)^T.
\end{equation}
Nevertheless, for
\begin{equation}
 p'=\frac{999}{1000}p+\frac1{1000}e_3
 =\frac1{61601000}(15945039,22797180,0,61601,22797180)^T
\end{equation}
one has
\begin{equation}
 E(p)-E(p')=\frac{1707687919}{246404000000000}>0.
\end{equation}

For every real $r\geq3$, the triangle of step $m=-r$ satisfies
\begin{enumerate}
\item $T_{-r}(n,k)>0$ for every positive even $n$ and $1\leq k\leq n$;
\item $T_{-r}(n,k)<0$ for every odd $n\geq3$ and $1<k<n$.
\end{enumerate}
In particular, the three OEIS conjectures and Conjecture~2 of
\cite{chen} hold for their stated integer parameters.

For integer $m$, every positive even row is entrywise nonnegative
if and only if $m\leq-3$ or $m\geq0$. For exactly these parameters,
every positive even row is in fact strictly positive.

Every four-qubit density matrix satisfies
\begin{equation}
 \norm{T_{AB}}_F^2+\norm{T_{AC}}_F^2+\norm{T_{AD}}_F^2\leq3.
\end{equation}
The constant is attained by both $|0000\rangle$ and
$(|0000\rangle+|1111\rangle)/\sqrt2$.

For every four-qubit state, pure or mixed,
\begin{equation}
 v_{B|A}^{2/3}+v_{C|A}^{2/3}+v_{D|A}^{2/3}\leq1.
\end{equation}
Equality holds for a Bell state on $AB$ tensored with any state on $CD$.

For the state \eqref{eq:rho},
\begin{equation}
 \E(\rho)\le\frac{417965512477}{90316800000000}
 <\min_{S(a,b,d)\in\Sep_3}\D(\rho,S(a,b,d))
 =\frac{109}{23520}.
\end{equation}
Thus Eqs.~(A8), (A11), and their common form in Eq.~(16) of \cite{CAW}
do not contain a closest fully separable state at this instance.

The contents of Copeland's array are
\begin{equation}
 c_n=\begin{cases}
 1,& n=0,\ n=1,\ \text{or }n\text{ is even},\\
 2,& n\geq3\text{ is odd}.
 \end{cases}
\end{equation}

Let $H=(g_{i+k})_{i,k<N}$ have determinant $1$ and let $c,d$ satisfy
\eqref{orth}, with $c$ monic of degree $N$ and $\deg d<N$.
Extend their coefficients by zero. Then
\begin{equation}
 (H^{-1})_{ik}=-\sum_{v=0}^{k}
 (c_{i+k+1-v}d_v-d_{i+k+1-v}c_v).
\end{equation}

Let \(U(t)\in1+t\mathbb Z[[t]]\), and write
\(c(n,k)=[t^k]U(t)^n\) for \(n\ge1\), \(k\ge0\).
Let the nonnegative exponent $E(n,k)$ have one of the forms
\begin{align*}
 E(n,k)&=rk+s &&(r,s\ge1),\\
 E(n,k)&=rn+sk+q &&(r\ge1,\ s,q\ge0),\\
 E(n,k)&=n+k-1.
\end{align*}
All parameters here are integers. Then
the series
\begin{equation}
 A_{U,E}(x)=\exp\left(\sum_{n\ge1,k\ge0}
                      c(n,k)^{E(n,k)}\frac{x^{n+k}}{n}\right)
\end{equation}
belongs to \(1+x\mathbb Z[[x]]\).

For \(U\in\mathbb Z[[t]]\), \(n\ge1\), \(k\ge0\), and prime \(p\),
\begin{align}
 n&\mid k\,c(n,k),\\
 c(pn,pk)&\equiv c(n,k)\pmod {p^{v_p(n)+1}}.
\end{align}

Under the hypotheses of Theorem~\ref{thm:general}, put
\(F(n,k)=c(n,k)^{E(n,k)}\). Then
\begin{equation}
 n\mid kF(n,k),\qquad
 F(pn,pk)\equiv F(n,k)\pmod {p^{v_p(n)+1}}
\end{equation}
for every \(n\ge1\), \(k\ge0\), and prime \(p\).

Let \(F(n,k)\in\mathbb Z\), \(n\ge1\), \(k\ge0\), satisfy
\eqref{eq:array}. Define
\begin{equation}
 g_m=\sum_{n=1}^m\frac{m}{n}F(n,m-n),\qquad m\ge1.
\end{equation}
Then \(g_m\in\mathbb Z\), and for every prime \(p\), \(m\ge1\),
\begin{equation}
 g_{pm}\equiv g_m\pmod {p^{v_p(m)+1}}.
\end{equation}
Consequently
\begin{equation}
 \exp\left(\sum_{m\ge1}g_m\frac{x^m}{m}\right)
  =\prod_{m\ge1}(1-x^m)^{-h_m}\in1+x\mathbb Z[[x]],
 \qquad h_m=\frac1m\sum_{d\mid m}\mu(d)g_{m/d}\in\mathbb Z.
\end{equation}

Suppose integers $c_m$, $m\geq1$, satisfy
\begin{equation}
 c_{pm}\equiv c_m\pmod{p^{\vp(m)+1}}
 \qquad(p\text{ prime},\ m\geq1).
\end{equation}
Then $\exp(\sum_{m\geq1}c_mx^m/m)$ has integer coefficients.

Let $n\geq1$, $b,t\geq0$ be integers with $n\mid tb$. Then
\begin{equation}
 b^{pt+1}\equiv b^{t+1}\pmod{p^{\vp(n)+1}}
 \quad(p\text{ prime}).
\end{equation}
Also, if $e\geq n$ and $n\mid eb$, then
\begin{equation}
 b^{pe}\equiv b^e\pmod{p^{\vp(n)+1}}.
\end{equation}

Let $F(n,k)\in\Z$ for $n\geq1$, $k\geq0$. Suppose
\begin{equation}
 n\mid kF(n,k),\qquad
 F(pn,pk)\equiv F(n,k)\pmod{p^{\vp(n)+1}}
\end{equation}
for every prime $p$. Then
$\exp(\sum_{n\geq1,k\geq0}F(n,k)x^{n+k}/n)\in1+x\Z[[x]]$.

For all $n,k\geq1$,
\begin{equation}
 T(n,k)=b(n)+b(k)-2.
\end{equation}
Consequently,
\begin{equation}
 a(2m+1)=2^{m+1}+4,\qquad a(2m+2)=3\cdot2^m+4\quad(m\geq0),
\end{equation}
and $\sum_{n\geq1}a(n)x^n=x(6+x-11x^2)/((1-x)(1-2x^2))$.

For every family satisfying \eqref{family}, every real parameter vector,
and every permutation $\tau$ of $I$,
\begin{equation}
\scal{\Theta_k(\tau)}=
\sum_{S\subseteq I}\eta(|S|)(-1)^{\inv(\tau,S)}
\prod_{i\in S}w_i\prod_{i\notin S}(1-w_i).
\end{equation}
No star condition is required.

Let $B_i$ be pairwise anticommuting bivectors with
$B_i^2=\varepsilon_i\in\{-1,1\}$. For arbitrary real $c_i,s_i$, put
$U_i=c_i+s_iB_i$. Then for every return order,
\begin{equation}
t(\Theta_k(\tau))=
\sum_{S\subseteq I}(-1)^{|S|(|S|+1)/2+\inv(\tau,S)}
\prod_{i\in S}(\varepsilon_i s_i^2)\prod_{i\notin S}c_i^2.
\end{equation}

Every mixed-sign family of Corollary~\ref{mixed} has the exact chain formula
\begin{equation}
t(U_1\cdots U_k)=
\begin{cases}
\prod_i c_i,&k\text{ even},\\
\prod_i c_i+t(B_I)\prod_i s_i,&k\text{ odd}.
\end{cases}
\end{equation}
The star condition is automatic unless $k\equiv3\pmod4$;
in that remaining case it is equivalent to $t(B_I)=0$.

If $X_1,\ldots,X_n$ are independent geometric random variables on
$\{1,2,\ldots\}$ with success probability $p\in(0,1]$ and $q=1-p$, then
\begin{equation}
 \E\Dstar(X)=
 \sum_{j=1}^{n}\frac{(-1)^{j+1}\binom nj}{1-q^j}
 +\frac{n-2}{p}-\frac{n-1}{p(2-p)}.
\end{equation}

For bipartite $G,H$, the following conditions are equivalent:
\begin{enumerate}
\item $G\sim H$;
\item some output relabelling $\sigma$ gives
$\Row B_{G^\sigma}=\Row B_H$;
\item some output relabelling $\sigma$ gives
$\rho_{G^\sigma}(S)=\rho_H(S)$ for every $S\subseteq O$.
\end{enumerate}

For all positive labels and all $1\le i\le n$,
\begin{equation}
 R_i=i+b_i=\fl{(i+1)\ph}-1,\qquad
 \deg_{J_n(1)}(v_i)=\min\{i,n-b_i\}.
\end{equation}
Consequently, for every $n\ge1$,
\begin{equation}
 \Delta_n=\fl{\frac{n+2}{\ph}}-1.
\end{equation}

Let $n,m\ge1$, set $x_n=\{(n+2)/\ph\}$ and $\alpha=2/\ph-1=\sqrt5-2$.
Then
\begin{equation}
 \Delta_{n+m}-\Delta_n-\Delta_m
 =\fl{x_n+x_m-\alpha}
 =\begin{cases}
 -1,&x_n+x_m<\alpha,\\
 0,&\alpha\le x_n+x_m<1+\alpha,\\
 1,&1+\alpha\le x_n+x_m.
 \end{cases}
\end{equation}
All three values occur for distinct orders at least three.

The first open problem on page 11 of \cite{original} has the following
partition. Set $\beta=5/\ph-3>0$, $k_0=1$ and, for $q\ge1$, set
\begin{equation}
 k_q=\left\lceil\frac{q-\alpha}{\beta}\right\rceil
     =\fl{(5q-1)\ph}+3q.
\end{equation}
Take $P_0=\{1,\ldots,5k_1-1\}$ and
$P_q=\{5k_q,\ldots,5k_{q+1}-1\}$ for $q\ge1$. These partition the
positive integers, and whenever $n=5k\in P_q$,
\begin{equation}
 \Delta_{5k}=3k+q.
\end{equation}
In particular $P_0=[1,44]$, $P_1=[45,99]$ and $P_2=[100,154]$.

If $A\in\mathcal M(E)$ has $\nssp$ and $E$ has $c$ weak components,
including isolated vertices, then
\begin{equation}
 n\ \leq\ \dim_\R\Zc(A)\ \leq\ \dim\ker B
   =m-n+c,\qquad m\geq2n-c.
\end{equation}

For $n,k\geq0$ and $m\geq1$, put $N=n+m$.
The following identities also hold at $m=0$ with empty products:
\begin{align}
B(n,k,m)&=\Schur_{(k^m)}(1,2,\ldots,N)\\
&=\frac{1}{\prod_{i=0}^{m-1}(n+i)!}
\sum_{n\geq j_1\geq\cdots\geq j_m\geq0}
(-1)^{\sum_tj_t}
\prod_{1\leq q<p\leq m}(j_q-j_p+p-q)^2\notag\\[-2pt]
&\hspace{32mm}\cdot
\prod_{t=1}^{m}
\frac{(n+t-1)_{\underline{j_t}}(n-j_t+t)^{n+k}}
{(j_t+m-t)!}.
\end{align}

For $n,m\geq1$ and any integer $a$, with $N=n+m$,
\begin{equation}
F(n,m;a)=
\begin{cases}
\Schur_{((a-n)^m)}(1,\ldots,N),&a\geq n,\\
0,&-m<a<n,\\
\displaystyle\frac{(-1)^{nm}}{(N!)^{m+r}}
\Schur_{(r^n)}(1,\ldots,N),&a=-m-r,\quad r\geq0.
\end{cases}
\end{equation}
For $n=0$, instead $F(0,m;a)=(m!)^a$ for every integer $a$.

For $n\geq0,m\geq1$, Kurkov's FORMULA conjecture in OEIS A132393,
dated 24 May 2026, holds:
\begin{equation}
\stir{n+m+1}{m+1}=(n+m)!\prod_{t=1}^m(n+t)^t\,R(n,m).
\end{equation}

For every integer $n\geq0$,
\begin{equation}
a_n=4\bin{2n+4}{n+2}+4\bin{2n+2}{n+1}+\bin{2n}{n}
       -72\cdot2^n+16n+40.
\end{equation}
Consequently, for every integer $n\geq6$,
\begin{equation}
\begin{aligned}
0={}&2(n+2)a_n-(17n+23)a_{n-1}+(47n+36)a_{n-2}\\
 &-2(22n+17)a_{n-3}+4(20-n)a_{n-4}\\
 &+8(2n-9)a_{n-5}+24(12n-47).
\end{aligned}
\end{equation}

Let $u_n=T(2n,n)$ for $n\geq0$ (A027171), and
$v_n=T(2n-1,n-1)$ for $n\geq1$ (A027175). Then
\begin{equation}
2(n+1)f_n-(7n+5)f_{n-1}+2(3-2n)f_{n-2}+12(1-3n)=0
\end{equation}
holds for $f=u$, $n\geq2$, and for $f=v$, $n\geq3$.

For $b_n=\sum_{k=0}^{\lfloor n/2\rfloor}T(n,k)$, $n\geq0$ (A027179),
put
\begin{align*}
p_0(n)&=-(n+2)(3n-20),&p_1(n)&=-(n+1)(3n-11),\\
p_2(n)&=33n^2-180n-100,&p_3(n)&=15n^2-56n+1,\\
p_4(n)&=2(-51n^2+313n-208),&p_5(n)&=-12(n-1)(n-4),\\
p_6(n)&=8(9n-11)(n-5).
\end{align*}
Then Mathar's seven-term recurrence holds for every $n\geq6$:
\begin{equation}
\sum_{j=0}^6p_j(n)b_{n-j}+4(-24n^2+196n-365)=0.
\end{equation}

There is a unique series $A\in\mathbb Q[[x]]$ satisfying
\eqref{eq:series}, and its coefficients are
\begin{equation}
 a_n=\frac{F(n)C_n}{2(n+1)(n+2)(2n-1)}-1\qquad(n\geq0).
\end{equation}
For every integer $n\geq4$ they satisfy Mathar's recurrence
\begin{align}
0={}&-(n+2)(404489n-1866368)a_n\notag\\
&+(3147815n^2-8680082n-14098754)a_{n-1}\notag\\
&+2(-2336439n^2+652022n+14514849)a_{n-2}\notag\\
&+8(-1044770n^2+10585023n-20370553)a_{n-3}\notag\\
&+8(642982n-2004177)(2n-9)a_{n-4}.
\end{align}

Put $G(t)=2t^4-9t^3+19t^2+18t-24$. Then $b_0=b_1=1$, and
\begin{equation}
 b_n=\frac{G(n)C_n}{4(n+1)(n+2)(2n-1)}\qquad(n\geq2).
\end{equation}
For $n\geq4$, Mathar's A174195 recurrence holds:
\begin{align}
0={}&2(n+2)(2013n^2-10435n+41550)b_n\notag\\
&+(4026n^3-128025n^2+34955n+59010)b_{n-1}\notag\\
&-2(2n-5)(20130n^2-110855n+93819)b_{n-2}.
\end{align}
The left side is $13998$ at $n=2$ and $57576$ at $n=3$;
thus $n\geq4$ is the exact range among integers $n\geq2$.

Let $n\ge3$, $\|z\|=1$, and $\langle z,x\rangle=\langle z,y\rangle=0$.
For arbitrary real symmetric off-diagonal weights $a_{ij}$,
\begin{equation}
 \sum_{i<j}a_{ij}p_{ij}^{\,2}
 \ \le\ \sum_{i<j<k}\max\{a_{ij},a_{ik},a_{jk}\}\,q_{ijk}^{\,2}.
\end{equation}
In particular, this proves the inequality for every real orthonormal triple
and every positive-entry symmetric matrix.

Under the vector hypotheses of Theorem~\ref{thm:main}, every pair family satisfies
\begin{equation}
 \sum_{\{i,j\}\in F,\ i<j}p_{ij}^2
 \ \le\ \sum_{\{i,j,k\}\in N(F),\ i<j<k}q_{ijk}^2.
\end{equation}

Let $A\in\R^{n\times n}$ be symmetric and $x\in\R^n$ satisfy
$\Delta=x^{\mathsf T}Ax\ne0$. Put $w=Ax$ and
$M=A-ww^{\mathsf T}/\Delta$. Then
\begin{equation}
\In(M)=
\begin{cases}
(n_+(A)-1,\ n_-(A),\ n_0(A)+1),&\Delta>0,\\
(n_+(A),\ n_-(A)-1,\ n_0(A)+1),&\Delta<0.
\end{cases}
\end{equation}
Moreover,
\begin{equation}
\ker M=\ker A\oplus\Span\{x\},\qquad \rank M=\rank A-1.
\end{equation}

Let $Y$ be a nonempty connected topological space, and let
$d,x:Y\to\R^n$ be continuous. For $y\in Y$ define
\begin{align*}
D(y)&=\diag(d_1(y),\ldots,d_n(y)),\qquad
\Delta(y)=x(y)^{\mathsf T}D(y)x(y),\\
M(y)&=D(y)-\frac{D(y)x(y)x(y)^{\mathsf T}D(y)}{\Delta(y)}.
\end{align*}
Suppose $\Delta(y)\ne0$ and $M(y)\succeq0$ for every $y$.
Then exactly one of the following alternatives holds:
\begin{enumerate}
\item $\Delta(y)>0$ and every $d_i(y)\ge0$ for all $y$;
\item $\Delta(y)<0$ for all $y$, and there is a unique index $j$ such that
      $d_j(y)<0$ for every $y$ and $d_i(y)\ge0$ for every $i\ne j$ and every $y$.
\end{enumerate}

For every integer $L\geq5$ and $E\in\Z$,
\begin{equation}
 D_L(E)=\ind_{E=0}+\sum_{n=1}^{\lfloor L/5\rfloor}
 \frac L n\binom{L-4n-1}{n-1}b_n(E).
\end{equation}
In particular, the placement coefficient
\begin{equation}
 A_{L,n}=\frac L n\binom{L-4n-1}{n-1}
        =\frac L{L-4n}\binom{L-4n}{n}
 \qquad(1\leq n\leq\lfloor L/5\rfloor)
\end{equation}
is an integer.

If $L=5q$ and $q\geq1$, exactly five centre sets contain $q$ bubbles,
and
\begin{equation}
 D_{5q}(2k-q)\geq5\binom qk\quad(0\leq k\leq q).
\end{equation}
In particular, $D_{10m}(0)\geq5\binom{2m}m
\geq5\,4^m/(2m+1)$ for $m\geq1$.
More generally, for $h\in\Z$ with $|h|\leq m/4$ and $\delta\in\{0,1\}$,
\begin{equation}
 D_{10m}(2h+\delta)\geq\frac{5\,4^m}{2m+1}\exp(-4h^2/m).
\end{equation}

The positive-exponent expression in \cite[Eq.~(3.7)]{mbss},
\begin{equation}
 R(q,k)=5\,2^q\sqrt{\frac2{\pi q}}
       \exp\!\left(2q\left(\frac kq-\frac12\right)^2\right),
\end{equation}
is not a lower bound for $D_{5q}(2k-q)$ throughout the stated energy
range. An exact replacement is \eqref{eq:lower}.

For $r\geq1$,
\begin{equation}
 B_{L,r}=\frac L2\sum_{k=1}^r\frac1k
   \binom{r-1}{k-1}^{\!2}
   \binom{L/2-4r+k-1}{2r-1}.
\end{equation}
The balanced bubble fragments, together with the vacuum, contribute
\begin{equation}
 Z_L^{\rm bal}=1+\sum_{r=1}^{\lfloor L/10\rfloor}
 B_{L,r}\binom{2r}r
\end{equation}
zero modes for every real $\Delta$. In particular,
$Z_{16}^{\rm bal}=65$, $Z_{18}^{\rm bal}=91$, and $Z_{20}^{\rm bal}=151$,
the lower-bound column of \cite[Table~II]{mbss}.

In a balanced fragment with $2r$ centres, the dimension of
$\ker H_3\cap\ker H_s$ is the Catalan number
\begin{equation}
 C_r=\binom{2r}r-\binom{2r}{r+1}
     =\frac1{r+1}\binom{2r}r.
\end{equation}
Thus the bubble subspace has exactly
$1+\sum_{r\geq1}B_{L,r}C_r$ simultaneous zero modes.
This gives $1,1,2,5,14,42,132$ for $n=0,2,4,6,8,10,12$ in
\cite[Table~III]{mbss}.

Let $H_S=\diag(E_0,\ldots,E_3)$ with strictly increasing energies. Let
$\ket\psi=\sum_k\alpha_k\ket k$ with $\alpha_k\ne0$ for every $k$.
If a map of the form \eqref{eq:thermal} preserves the populations of
$\ket\psi\bra\psi$, then its output has entries
\begin{equation}
\mathcal T(\ket\psi\bra\psi)_{jk}
=\alpha_j\overline{\alpha_k}\,g^{-1}\Tr(V_jV_k^\dagger)
\end{equation}
for four $g\times g$ unitary matrices $V_0,\ldots,V_3$.

Let $G$ be a finite nonabelian group, $z=|Z(G)|$, and
$n=|G\setminus Z(G)|$. Then $z\ge1$, $n\ge z+2\ge3$, and
\begin{equation}
 \ECN(\Gamma_c(G))\le n(n-z-2)<B(n).
\end{equation}
In particular, Conjecture~2 of~\cite[Section~4, p.~11]{NFDS} holds.

For every integer $n\ge1$, the following disjoint union is exact:
\begin{equation}
 W(n)=\{p\in\pr:p^3\le n\}\ \dot\cup\ E_2(n)\ \dot\cup\ E_3(n).
\end{equation}
In particular,
\begin{equation}
 a(n)=\pi(\lfloor n^{1/3}\rfloor)
 +\ind_{\{n<8,\ n\bmod4\in\{2,3\}\}}
 +\ind_{\{n<27,\ n\bmod3=2\}}.
\end{equation}
Thus $a(n)=\pi(\lfloor n^{1/3}\rfloor)$ for every $n\ge27$.

For every integer $n\geq1$ and every integer $X\geq0$,
\begin{align}
 \C_n(X)
 &=\sum_{\substack{d\mid n\\\mob(d)\ne0}}
       \C_d(\lfloor X/d\rfloor),\\
 \C_n(X)
 &=\sum_{\substack{1\leq q\leq X\\\rad(q)\mid n}}
       M(\lfloor X/q\rfloor).
\end{align}
All divisors and summation indices are positive.

For $n\geq1$ and any arithmetic function $F$,
\begin{align}
 \sum_{k=1}^{n}F((k,n))&=\sum_{d\mid n}F(d)\varphi(n/d),\\
 \sum_{k=1}^{n}F(n/(k,n))&=\sum_{d\mid n}F(d)\varphi(d).
\end{align}
Thus the finite gcd formulas of A007431, A063659 and A276833
\cite{a007431,a063659,a276833} follow, with local factors
\begin{align*}
 \mathrm{A007431}(p^e)&=
 \begin{cases}p-2,&e=1,\\p^{e-2}(p-1)^2,&e\geq2,\end{cases}\\
 \mathrm{A063659}(p^e)&=
 \begin{cases}p,&e=1,\\p^e-p^{e-2},&e\geq2,\end{cases}
 \qquad
 \mathrm{A276833}(n)=\prod_{p\mid n}(2-p).
\end{align*}
In addition $\sum_{d\mid n}\mathrm{A007431}(d)=\varphi(n)$.

For integers $X,Y\geq0$,
\begin{equation}
 \sum_{j=1}^{X}\sum_{k=1}^{Y}\mob(jk)
 =\sum_{d=1}^{\min(X,Y)}\mob(d)
   \C_d(\lfloor X/d\rfloor)\C_d(\lfloor Y/d\rfloor).
\end{equation}
Thus, for $T(N)=\sum_{j,k=1}^{N}\mob(jk)$ (A372700 \cite{a372700}),
\begin{equation}
 T(N)=\sum_{d=1}^{N}\mob(d)\C_d(\lfloor N/d\rfloor)^2
 \qquad(N\geq1).
\end{equation}

For $N\geq1$,
\begin{equation}
 T(N)=-1+2\sum_{k=1}^{N}\mob(k)a(k).
\end{equation}
In particular $T(N)=T(N-1)$ when $N$ is nonsquarefree.

Let $F$ be any complex-valued function on positive integers. For $n\geq1$
and $X\geq0$,
\begin{equation}
 \sum_{k=1}^{X}F\!\left(\frac{k}{(k,n)}\right)
 =\sum_{d\mid n}\ \sum_{\substack{1\leq m\leq\lfloor Xd/n\rfloor\\(m,d)=1}}F(m).
\end{equation}
In particular, if $A_F(d)=\sum_{m\leq d,(m,d)=1}F(m)$ and
$B_F(n)=\sum_{k\leq n}F(k/(k,n))$, then
\begin{equation}
 B_F(n)=\sum_{d\mid n}A_F(d),\qquad
 A_F(n)=\sum_{d\mid n}\mob(n/d)B_F(d).
\end{equation}

For $b(n)=\sum_{k\leq n}\mob(k/(k,n))$ (A332685 \cite{a332685}),
\begin{equation}
 b(n)=\sum_{d\mid n}a(d),\qquad
 a(n)=\sum_{d\mid n}\mob(n/d)b(d).
\end{equation}
Also $b(n)=\sum_{k\leq n}\mob(\operatorname{lcm}(n,k)/n)$.

The reduced numerators of $b_n$ repeat the block $(0,1,1,1,0,-1)$, with
least period six. For $n\ge12$,
\begin{equation}
 a_n=2a_{n-6}-a_{n-12}.
\end{equation}
Moreover, the ordinary generating function of the denominator sequence is
\begin{equation}
 \sum_{n\ge0}a_nz^n=
 \frac{1+z+z^2+2z^3+z^4+6z^5-z^6+2z^7+z^8+z^9-z^{10}}
 {(1-z^6)^2}.
\end{equation}
This is the generating function recorded as empirical by Colin Barker on
November 11, 2016, in A189733's FORMULA field.

For every $n\ge0$,
\begin{equation}
 B(n,0)=\sum_{j=0}^n(-1)^{n-j}\binom nj b_j=(-1)^{n+1}b_n.
\end{equation}

For $m\ge0$ and $d\ge1$,
\begin{equation}
 B(m,m+d)=(-1)^m\sum_{j=0}^{\lfloor(d-1)/2\rfloor}
 \frac{(-1)^j\binom{d-1-j}{j}}{m+j+1}.
\end{equation}
Together with $B(m,m)=0$ and
$B(m,n)=(-1)^{m+n+1}B(n,m)$, this determines the whole square array.

For all $n\ge0$,
\begin{align}
 \sum_{n\ge0}p_nz^n
 &=\frac{z+z^2+z^3-z^5}{1-z^6}
 =\frac{z(1+z^2-z^3)}{(1-z)(1-z+z^2)(1+z+z^2)},\\

 p_n&=\frac{1+(-1)^{\lfloor(n-1)/3\rfloor}}2
       -\left\lfloor\frac{n+1}{6}\right\rfloor
       +\left\lfloor\frac n6\right\rfloor.
\end{align}
For $n\ge5$,
\begin{equation}
 p_n=p_{n-1}-p_{n-2}+p_{n-3}-p_{n-4}+p_{n-5}.
\end{equation}
These are A278718's generating function and Hurt's formulas dated
October 3, 2017.

For every $k\ge0$,
\begin{equation}
 (c_{6k},\ldots,c_{6k+5})=(6k+1,2,3,2,6k+5,1).
\end{equation}
In particular, $c_n=2c_{n-6}-c_{n-12}$ for $n\ge12$, and
\begin{equation}
 \sum_{n\ge0}c_nz^n=
 \frac{\begin{gathered}1+2z+3z^2+2z^3+5z^4+z^5\\
       {}+5z^6-2z^7-3z^8-2z^9+z^{10}-z^{11}\end{gathered}}
      {(1-z^6)^2}.
\end{equation}
Thus both conjectures attributed to Barker on January 10, 2016, in
A267068 are true. Its other three FORMULA assertions hold, with the
OEIS offsets of the cited sequences~\cite{auxiliary}:
\begin{align}
 c_{2n+1}&=\mathrm{A130196}(n+1),\notag\\
 c_{\mathrm{A047245}(n+1)}&=\mathrm{A052901}(n+2),\\
 c_{3n}+c_{3n+1}+c_{3n+2}&=\mathrm{A047238}(n+3)\qquad(n\ge0).\notag
\end{align}

In the ring $\mathbb Z[x][[z]]$,
\begin{equation}
F(z,x):=\sum_{n\geq1}v_n(x)z^{n-1}
=\frac{1+z}{1-2z+(1-x)z^2}.
\end{equation}
For every $k\geq0$,
\begin{equation}
\sum_{n\geq1}(\coeff{k}{v_n})z^{n-1}
=\frac{z^{2k}(1+z)}{(1-z)^{2k+2}}.
\end{equation}
For $k\geq1$, the companion column generating function is
\begin{equation}
\sum_{n\geq1}(\coeff{k}{u_n})z^{n-1}
=\frac{z^{2k-1}(1+z)}{(1-z)^{2k+1}},
\end{equation}
and the constant column of $u_n$ has generating function $1/(1-z)$.

For $n\geq2$,
\begin{equation}
v_n(1)=3\cdot2^{n-2},\qquad u_n(1)=3\cdot2^{n-2}-1,
\end{equation}
whereas $v_1(1)=u_1(1)=1$. If $w_n=v_n(-1)$, then
\begin{equation}
\sum_{n\geq1}w_nz^{n-1}=\frac{1+z}{1-2z+2z^2},\quad
w_{n+2}=2w_{n+1}-2w_n,\quad w_1=1,\ w_2=3.
\end{equation}
